window.BRIDGE_PAGE_SOURCES=[{"name": "13-incremental-launching-moment-lab.html", "text": "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\"/>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>\n<link rel=\"icon\" href=\"data:,\"/>\n<title>把桥从岸边推过去，推到哪一步最危险？</title>\n<style>\n:root{\n  --paper:#f7f9f9;--panel:#fff;--panel-s:#f1f5f5;\n  --ink:#102a36;--muted:#60737b;--accent:#1f8fa8;\n  --beam:#24577a;--nose:#e69b36;--active:#0b8f72;\n  --pos:#247db4;--neg:#c85c4a;--compare:#7257b7;\n  --line:#d7e1e3;--shadow:0 12px 30px rgba(16,42,54,.08);--r:14px;\n  --ff:\"Microsoft YaHei\",\"PingFang SC\",\"Segoe UI\",sans-serif;\n  --fd:\"Bahnschrift\",\"Segoe UI\",\"Microsoft YaHei\",sans-serif;\n}\n*{box-sizing:border-box;margin:0}\nbody{min-height:100vh;font-family:var(--ff);color:var(--ink);background:var(--paper)}\n.page{max-width:1240px;margin:0 auto;padding:18px 16px 30px}\n\n.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow)}\n.lab-question{position:relative;margin-bottom:14px;padding:18px 20px 17px 24px;background:#eef5f6;border:1px solid #cbdfe3;border-radius:var(--r)}\n.lab-question::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(var(--accent),var(--nose));border-radius:var(--r) 0 0 var(--r)}\n.kicker{font:700 11px/1.2 var(--ff);letter-spacing:.12em;color:#397080;margin-bottom:7px}\n.lab-question h1{font:700 25px/1.25 var(--fd);margin-bottom:7px}\n.lab-question p{max-width:900px;font-size:14px;line-height:1.65;color:#35505a}\n.prediction{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:end;margin-top:13px;max-width:900px}\n.prediction label{display:block;font-size:12px;color:var(--muted);margin-bottom:5px}\n.prediction textarea{display:block;width:100%;min-height:50px;resize:vertical;padding:9px 11px;border:1px solid #b9ced2;border-radius:9px;background:#fff;color:var(--ink);font:13px/1.5 var(--ff)}\n.prediction-status{min-height:1.4em;margin-top:5px!important;font-size:11px!important;color:#56808a!important}\n.workspace{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(300px,.72fr);gap:14px;align-items:start}\n.scene{padding:15px 16px 14px;min-width:0}\n.scene-head{display:flex;justify-content:space-between;gap:12px;align-items:start;margin-bottom:8px}\n.scene-head h2{font-size:17px;margin-bottom:4px}\n.scene-head p{font-size:12px;line-height:1.55;color:var(--muted)}\n.legend{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:6px 11px;max-width:360px}\n.legend-item{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--muted);white-space:nowrap}\n.sw{width:10px;height:10px;border-radius:99px;flex:0 0 auto}\n\n/* controls */\n.controls{padding:16px;position:sticky;top:10px;background:#f9fbfb}\n.controls h2{font-size:16px;margin-bottom:4px}.controls>.hint{margin-bottom:11px}\n.cg{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:9px}\n.ctl{padding:10px 11px;border-radius:10px;background:#fff;border:1px solid var(--line)}\n.ctl-wide{grid-column:1/-1}\n.ctl label{display:block;margin-bottom:8px;font-size:12px;color:var(--muted)}\n.vr{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:8px}\n.vr strong{font-size:15px}.vr span{font-size:10px;color:var(--muted)}\ninput[type=range]{width:100%;accent-color:var(--accent)}\n.br{display:grid;gap:9px}\n.pos-ctl{padding:11px;border-radius:10px;background:#fff;border:1px solid var(--line)}\n.pos-ctl .vr strong{font-size:19px}\n.hint{font-size:11px;color:var(--muted);line-height:1.55;margin-top:4px}\n.side-stack{display:grid;grid-template-columns:1fr;gap:9px}\n.tbox{padding:11px;border-radius:10px;background:#fff;border:1px solid var(--line);display:flex;flex-direction:column;justify-content:space-between;gap:7px}\n.th{display:flex;justify-content:space-between;align-items:center;gap:8px}\n.th strong{font-size:15px}\ninput[type=checkbox]{width:18px;height:18px;accent-color:var(--accent)}\nbutton{min-height:44px;border:0;border-radius:9px;padding:10px 14px;font:600 13px/1 var(--ff);cursor:pointer;transition:transform .14s,box-shadow .14s}\nbutton:hover{transform:translateY(-1px);box-shadow:0 8px 16px rgba(0,109,119,.14)}\nbutton:focus-visible,input:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid rgba(31,143,168,.28);outline-offset:2px}\n.pri{color:#fff;background:linear-gradient(135deg,var(--accent),#009688)}\n.sec{color:var(--ink);background:rgba(32,48,64,.08)}\n.btns{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}\n\n/* stats */\n.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:14px 0}\n.stat{min-width:0;padding:11px 12px;border-radius:10px;background:var(--panel);border:1px solid var(--line)}\n.stat-l{font-size:11px;color:var(--muted);margin-bottom:8px;letter-spacing:.03em}\n.stat-v{font:700 18px/1.1 var(--fd);overflow-wrap:anywhere}\n.stat-n{margin-top:6px;font-size:11px;color:var(--muted)}\n\n/* viz */\n.viz-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.viz{padding:18px 20px 16px;overflow:hidden}\n.viz h2{font-size:16px;margin-bottom:4px}\n.viz p{font-size:12px;color:var(--muted);line-height:1.55;margin-bottom:10px}\n.cw{position:relative;border-radius:10px;overflow:hidden;border:1px solid var(--line);background:#fffdf9;margin-bottom:10px}\n.cw:last-child{margin-bottom:0}\nsvg{display:block;width:100%;height:auto;touch-action:none}\n.ft{position:absolute;right:9px;top:8px;background:rgba(255,255,255,.88);border:1px solid var(--line);padding:5px 8px;border-radius:7px;font-size:10px;color:var(--muted);z-index:2}\n.teaching{margin-top:10px;padding:12px 14px;border-radius:14px;\n  background:rgba(11,143,114,.07);border:1px solid rgba(11,143,114,.1);\n  font-size:12px;line-height:1.7;color:var(--ink)}\n.fn{margin-top:10px;font-size:11px;color:var(--muted);line-height:1.65}\n.insight{margin-top:14px;padding:18px 20px;background:#102a36;color:#f4f8f9;border-radius:var(--r)}\n.insight .kicker{color:#7dc8d8}.insight h2{font-size:18px;margin-bottom:7px}.insight p{font-size:13px;line-height:1.7;color:#dbe7ea}.terms{margin-top:9px;font:600 11px/1.5 var(--ff);letter-spacing:.04em;color:#f3bd6c!important}\n.model-permission{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin-top:14px;overflow:hidden;border:1px solid var(--line);border-radius:var(--r);background:var(--line)}\n.model-permission div{padding:13px 14px;background:#fff}.model-permission strong{display:block;margin-bottom:5px;font-size:11px;color:#367080}.model-permission span{display:block;font-size:11px;line-height:1.55;color:var(--muted)}\n.provenance{margin-top:9px;font-size:10px;line-height:1.55;color:#7b8b91}\n\n@media(max-width:1100px){\n  .workspace{grid-template-columns:1fr}.controls{position:static}.cg{grid-template-columns:repeat(3,1fr)}.ctl-wide{grid-column:auto}.side-stack{grid-template-columns:1fr 1fr}.stats{grid-template-columns:repeat(3,1fr)}\n}\n@media(max-width:680px){\n  .page{padding:10px 8px 20px}.lab-question{padding:16px 14px 15px 18px}.lab-question h1{font-size:21px}.prediction{grid-template-columns:1fr}.scene{padding:12px 10px}.scene-head{display:block}.legend{justify-content:flex-start;margin-top:8px}.cg{grid-template-columns:1fr 1fr}.side-stack,.viz-grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.model-permission{grid-template-columns:1fr 1fr}svg text{font-size:28px!important}.ft{position:static;border:0;border-bottom:1px solid var(--line);border-radius:0;padding:7px 9px}\n}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}\n</style>\n</head>\n<body>\n<div class=\"page\">\n  <section class=\"lab-question\" aria-labelledby=\"lab-title\">\n    <div class=\"kicker\">桥还没架完时，会怎样受力？</div>\n    <h1 id=\"lab-title\">把桥从岸边推过去，推到哪一步最危险？</h1>\n    <p>先别装任何辅助构件。把桥慢慢向前推，选出你认为最吃力的一步，再用曲线核对。是伸出去最长的时候，刚碰到下一个桥墩的时候，还是别的时刻？</p>\n    <p class=\"scope-note\">本关先用弯曲效应的大小比较施工阶段；曲线中的“弯矩”描述这种效应。材料强度、失稳和连接破坏还需另外检查，因此这里不直接判定真实桥梁是否安全。</p>\n    <div class=\"prediction\">\n      <div>\n        <label for=\"predictionText\">我现在的判断</label>\n        <textarea id=\"predictionText\" placeholder=\"写下你选择的施工位置，以及为什么认为这里最吃力。\"></textarea>\n        <p class=\"prediction-status\" id=\"predictionStatus\" aria-live=\"polite\"></p>\n      </div>\n      <button id=\"savePrediction\" class=\"sec\" type=\"button\">留住这句话</button>\n    </div>\n  </section>\n\n  <div class=\"workspace\">\n    <section class=\"card scene\" aria-labelledby=\"scene-title\">\n      <div class=\"scene-head\">\n        <div><h2 id=\"scene-title\">梁正在经过哪些支点</h2><p>拖动梁体或“顶推进度”。点梁上的一截，也可以用右侧滑杆选截面。</p></div>\n        <div class=\"legend\" aria-label=\"图例\">\n          <div class=\"legend-item\"><span class=\"sw\" style=\"background:var(--beam)\"></span>主梁</div>\n          <div class=\"legend-item\"><span class=\"sw\" style=\"background:var(--nose)\"></span>导梁</div>\n          <div class=\"legend-item\"><span class=\"sw\" style=\"background:var(--active)\"></span>受力支点</div>\n          <div class=\"legend-item\"><span class=\"sw\" style=\"background:var(--pos)\"></span>正弯矩</div>\n          <div class=\"legend-item\"><span class=\"sw\" style=\"background:var(--neg)\"></span>负弯矩</div>\n        </div>\n      </div>\n      <div class=\"cw\"><div class=\"ft\">可拖动 · 可点选截面</div><svg id=\"svgStruct\" viewBox=\"0 0 960 260\" role=\"img\" aria-label=\"顶推梁、导梁和桥墩的相对位置\"></svg></div>\n      <div class=\"cw\"><div class=\"ft\" id=\"tagMoment\">当前弯矩图</div><svg id=\"svgMoment\" viewBox=\"0 0 960 280\" role=\"img\" aria-label=\"当前施工阶段的归一化弯矩图\"></svg></div>\n      <div class=\"teaching\" id=\"teachText\" aria-live=\"polite\">推进梁体，观察同一截面的弯矩方向是否会改变。</div>\n    </section>\n\n    <aside class=\"card controls\" aria-labelledby=\"control-title\">\n      <h2 id=\"control-title\">改变施工条件</h2>\n      <div class=\"hint\">先只动顶推进度；看出一次越过零线以后，再改变导梁。</div>\n      <div class=\"br\">\n        <div class=\"pos-ctl\">\n          <label for=\"rPos\">把桥向前推</label>\n          <div class=\"vr\"><strong id=\"vPos\">0.0 m</strong><span>主梁前端位置</span></div>\n          <input id=\"rPos\" type=\"range\" min=\"0\" max=\"1000\" step=\"1\" value=\"170\"/>\n        </div>\n        <div class=\"pos-ctl\">\n          <label for=\"rTrack\">跟踪哪一截梁</label>\n          <div class=\"vr\"><strong id=\"vTrack\">尚未选择</strong><span>距梁头</span></div>\n          <input id=\"rTrack\" type=\"range\" min=\"50\" max=\"900\" step=\"10\" value=\"330\"/>\n          <div class=\"hint\">动一下滑杆，便会锁定一截随梁一起前进的截面。</div>\n        </div>\n      </div>\n      <div class=\"cg\">\n        <div class=\"ctl\"><label for=\"rPierCount\">桥墩数量</label><div class=\"vr\"><strong id=\"vPierCount\">5</strong><span>个</span></div><input id=\"rPierCount\" type=\"range\" min=\"3\" max=\"8\" step=\"1\" value=\"5\"/></div>\n        <div class=\"ctl\"><label for=\"rSpan\">标准跨径</label><div class=\"vr\"><strong id=\"vSpan\">40 m</strong><span>墩间距</span></div><input id=\"rSpan\" type=\"range\" min=\"30\" max=\"60\" step=\"2\" value=\"40\"/></div>\n        <div class=\"ctl\"><label for=\"rNoseLen\">导梁长度</label><div class=\"vr\"><strong id=\"vNoseLen\">0.65 跨</strong><span>相对跨径</span></div><input id=\"rNoseLen\" type=\"range\" min=\"0.30\" max=\"0.90\" step=\"0.05\" value=\"0.65\"/></div>\n        <div class=\"ctl\"><label for=\"rNoseW\">导梁线重</label><div class=\"vr\"><strong id=\"vNoseW\">0.25 q</strong><span>相对主梁</span></div><input id=\"rNoseW\" type=\"range\" min=\"0.10\" max=\"0.50\" step=\"0.01\" value=\"0.25\"/></div>\n        <div class=\"ctl\"><label for=\"rNoseEI\">导梁刚度</label><div class=\"vr\"><strong id=\"vNoseEI\">0.25 EI</strong><span>相对主梁</span></div><input id=\"rNoseEI\" type=\"range\" min=\"0.10\" max=\"1.00\" step=\"0.05\" value=\"0.25\"/></div>\n        <div class=\"ctl\"><div class=\"th\"><strong>装上导梁</strong><input id=\"cbNose\" type=\"checkbox\" aria-label=\"装上或拆下钢导梁\"/></div><div class=\"hint\">轻与硬是两件事，可以分别改变。</div></div>\n      </div>\n      <input id=\"rMScale\" type=\"hidden\" value=\"0\"/><span id=\"vMScale\" hidden>自动</span>\n      <div class=\"tbox\">\n        <div class=\"hint\">动画便于看路径；包络用来找全过程极值。</div>\n        <div class=\"btns\">\n          <button id=\"btnPlay\" class=\"sec\" type=\"button\">▶ 播放</button>\n          <button id=\"btnSweep\" class=\"pri\" type=\"button\">计算全过程包络</button>\n          <button id=\"btnReset\" class=\"sec\" type=\"button\">回起点</button>\n        </div>\n      </div>\n    </aside>\n  </div>\n\n  <section class=\"stats\">\n    <div class=\"stat\"><div class=\"stat-l\">当前阶段</div><div class=\"stat-v\" id=\"sStage\">--</div><div class=\"stat-n\" id=\"sStageN\"></div></div>\n    <div class=\"stat\"><div class=\"stat-l\">受力支点</div><div class=\"stat-v\" id=\"sSupN\">0</div><div class=\"stat-n\" id=\"sSupD\"></div></div>\n    <div class=\"stat\"><div class=\"stat-l\">最大正弯矩 M*</div><div class=\"stat-v\" id=\"sMpos\" style=\"color:var(--pos)\">0.000</div><div class=\"stat-n\">M*=M/(qL²)</div></div>\n    <div class=\"stat\"><div class=\"stat-l\">最大负弯矩 M*</div><div class=\"stat-v\" id=\"sMneg\" style=\"color:var(--neg)\">0.000</div><div class=\"stat-n\">M*=M/(qL²)</div></div>\n    <div class=\"stat\"><div class=\"stat-l\">支座是否要“向下拉”</div><div class=\"stat-v\" id=\"sReaction\">--</div><div class=\"stat-n\" id=\"sReactionN\">检查负反力</div></div>\n    <div class=\"stat\"><div class=\"stat-l\">导梁对负弯矩峰值</div><div class=\"stat-v\" id=\"sImpr\">--</div><div class=\"stat-n\" id=\"sImprN\">同一阶段对比</div></div>\n  </section>\n\n  <section class=\"viz-grid\">\n    <div class=\"card viz\">\n      <h2>盯住这一截：全过程弯矩历程</h2>\n      <p>横轴不是桥上的位置，而是时间顺序。曲线穿过零线，说明同一截面换过受力角色。</p>\n      <div class=\"cw\"><div class=\"ft\" id=\"tagHistory\">先选择一截梁</div><svg id=\"svgHistory\" viewBox=\"0 0 960 280\" role=\"img\" aria-label=\"所选截面的归一化弯矩历程\"></svg></div>\n      <div class=\"fn\">实线为无导梁，虚线为有导梁。不要只看峰值，也看它在哪个支承状态出现。</div>\n    </div>\n    <div class=\"card viz\">\n      <h2>扫过整条路：正、负弯矩包络</h2>\n      <p>包络把许多施工照片叠在一起。它回答“哪里曾经最不利”，不回答“为什么”。</p>\n      <div class=\"cw\"><div class=\"ft\" id=\"tagEnvelope\">尚未计算</div><svg id=\"svgEnvelope\" viewBox=\"0 0 960 280\" role=\"img\" aria-label=\"顶推全过程的归一化正负弯矩包络\"></svg></div>\n      <div class=\"fn\" id=\"envSummary\">先拖动观察单个阶段，再计算全过程包络。截面历程图是本页核心——它展示了顶推施工中同一截面反复经历正负弯矩交替的过程。</div>\n    </div>\n  </section>\n\n  <section class=\"insight\" aria-labelledby=\"insight-title\">\n    <div class=\"kicker\">看见以后，再给它名字</div>\n    <h2 id=\"insight-title\">为什么成桥验算不能代替施工阶段验算？</h2>\n    <p>同一截梁向前走，边界条件不断改变；自重在哪一种体系里进入，内力就在哪一种体系里留下痕迹。导梁也不是简单地“减小弯矩”：它用较轻、较柔的前端更早找到下一支点，同时可能改写支座反力和另一些阶段。真正不变的是平衡与变形协调，变化的是力从哪条路回到地面。</p>\n    <p>这不只属于桥梁。一个系统若是分阶段形成的——装配、张拉、升温、上线、交接——终局看起来相同，也不能保证沿途留下的状态相同。先问“它是怎样走到这里的”，常常比只看最后一张图更有用。</p>\n    <p class=\"terms\">对应术语：施工阶段分析 · 路径依赖 · 弯矩历程 · 弯矩包络 · 支座反力</p>\n  </section>\n\n  <section class=\"model-permission\" aria-label=\"模型的权限\">\n    <div><strong>保留</strong><span>线弹性梁、分阶段支承、分布自重、导梁相对线重与刚度。</span></div>\n    <div><strong>舍弃</strong><span>预应力、收缩徐变、摩阻、接缝、横向偏心、局部应力与施工误差。</span></div>\n    <div><strong>可以回答</strong><span>内力正负如何轮换，哪一施工阶段更敏感，参数改变后的趋势。</span></div>\n    <div><strong>不可用于</strong><span>实际桥梁弯矩、顶推力、构件尺寸或施工安全结论。</span></div>\n  </section>\n  <p class=\"provenance\">模型量采用 q=1、主梁 EI=1，并以跨径 L 归一化；页面数值为教学比较量，不是工程计算书。原型来自“html演示文档/pushing_demo(1).html”，本版重排界面、补充反力核查与模型权限。</p>\n</div>\n\n<script>\n\"use strict\";\n\n/* ===== 状态 ===== */\nconst S={\n  nPier:5, span:40, noseRatio:0.65, noseW:0.25, noseEI:0.25,\n  withNose:false, posT:0.17, frontX:0,\n  playing:false, envelope:null,\n  trackLocal:-1,\n  trackHistory:null,\n  mScaleManual:0       // 0=自动, >0=手动纵轴范围\n};\n\n/* ===== DOM ===== */\nconst $=id=>document.getElementById(id);\nconst el={\n  rPierCount:$(\"rPierCount\"),rSpan:$(\"rSpan\"),rNoseLen:$(\"rNoseLen\"),\n  rNoseW:$(\"rNoseW\"),rNoseEI:$(\"rNoseEI\"),rPos:$(\"rPos\"),rTrack:$(\"rTrack\"),cbNose:$(\"cbNose\"),\n  rMScale:$(\"rMScale\"),vMScale:$(\"vMScale\"),\n  btnPlay:$(\"btnPlay\"),btnSweep:$(\"btnSweep\"),btnReset:$(\"btnReset\"),\n  vPierCount:$(\"vPierCount\"),vSpan:$(\"vSpan\"),vNoseLen:$(\"vNoseLen\"),\n  vNoseW:$(\"vNoseW\"),vNoseEI:$(\"vNoseEI\"),vPos:$(\"vPos\"),vTrack:$(\"vTrack\"),\n  sStage:$(\"sStage\"),sStageN:$(\"sStageN\"),sSupN:$(\"sSupN\"),sSupD:$(\"sSupD\"),\n  sMpos:$(\"sMpos\"),sMneg:$(\"sMneg\"),sReaction:$(\"sReaction\"),sReactionN:$(\"sReactionN\"),sImpr:$(\"sImpr\"),sImprN:$(\"sImprN\"),\n  svgStruct:$(\"svgStruct\"),svgMoment:$(\"svgMoment\"),\n  svgHistory:$(\"svgHistory\"),svgEnvelope:$(\"svgEnvelope\"),\n  tagMoment:$(\"tagMoment\"),tagHistory:$(\"tagHistory\"),\n  tagEnvelope:$(\"tagEnvelope\"),teachText:$(\"teachText\"),envSummary:$(\"envSummary\"),\n  predictionText:$(\"predictionText\"),predictionStatus:$(\"predictionStatus\"),savePrediction:$(\"savePrediction\")\n};\n\n/* ===== 工具 ===== */\nconst clamp=(v,a,b)=>Math.max(a,Math.min(b,v));\nconst fmt=(v,d=2)=>Number.isFinite(v)?v.toFixed(d):\"--\";\nconst normM=v=>v/(S.span*S.span);\nconst EPS=1e-8;\nlet dragging=false;\n\n/* ===== 几何 ===== */\nfunction geom(wn){\n  const withNose=wn!==undefined?wn:S.withNose;\n  // 桥墩位置：P1=0, P2=span, P3=2*span, ...\n  const piers=[];for(let i=0;i<S.nPier;i++)piers.push(i*S.span);\n  // 台座 = P1左侧的满跨支撑制梁场（从很远处到P1=0）\n  // 梁总长 = 跨径 × (墩数-1)\n  const bLen=(S.nPier-1)*S.span;\n  const nLen=withNose?S.noseRatio*S.span:0;\n  // frontX = 主梁前端(右端)的全局x坐标，这是顶推控制量\n  // 起始：frontX=0，主梁前端刚好在P1处（整根梁还在台座上）\n  // 结束：frontX=最后一个墩的x，主梁前端到达最后一个墩\n  const minFront=0;\n  const maxFront=piers[piers.length-1];\n  const frontX=clamp(S.frontX,minFront,maxFront);\n  // 梁后端(左端) = frontX - bLen，始终在台座上（P1左侧）\n  // 导梁前端 = frontX + nLen\n  return{piers,bLen,nLen,frontX,minFront,maxFront,\n    rearX:frontX-bLen, tipX:frontX+nLen,\n    vMin:-1.5*S.span, vMax:piers[piers.length-1]+1.5*S.span};\n}\nfunction syncFromT(){const g=geom(false);S.frontX=g.minFront+S.posT*(g.maxFront-g.minFront)}\nfunction syncToT(){const g=geom(false);S.posT=clamp((S.frontX-g.minFront)/(g.maxFront-g.minFront),0,1)}\n\n/* ===== 有限元求解器 ===== */\nfunction uniqueSorted(arr){\n  const s=[...arr].sort((a,b)=>a-b),o=[];\n  for(const v of s)if(!o.length||Math.abs(v-o[o.length-1])>1e-6)o.push(v);\n  return o;\n}\n\nfunction buildNodes(g){\n  // 有限元只建模从P1(x=0)到梁/导梁前端的悬出部分\n  // P1左侧在台座上完全支撑，弯矩=0\n  // 悬出长度 = frontX（主梁悬出）+ nLen（导梁）\n  const overhang=g.frontX+g.nLen; // 从P1到导梁前端的总长度\n  if(overhang<EPS)return{nodes:[],active:[],feLen:0,mainLenFe:0};\n\n  const feLen=overhang;\n  const mainLenFe=g.frontX; // 主梁在有限元内的长度\n\n  // 找P1右侧、在悬出范围内的桥墩（P1自身在feLocal=0处）\n  const active=[];\n  for(let i=0;i<g.piers.length;i++){\n    const px=g.piers[i];\n    if(px>=-EPS && px<=g.frontX+g.nLen+EPS){\n      active.push({x:px,kind:\"pier\",label:\"P\"+(i+1),feLocal:px});\n    }\n  }\n  if(active.length===0)return{nodes:[],active:[],feLen:0,mainLenFe:0};\n\n  const supLocals=active.map(p=>p.feLocal);\n  const anchors=[0,mainLenFe,feLen,...supLocals];\n  const keys=uniqueSorted(anchors.filter(v=>v>=-EPS&&v<=feLen+EPS));\n  const step=S.span/10;\n  const nodes=[];\n  for(let i=0;i<keys.length-1;i++){\n    const a=keys[i],b=keys[i+1];\n    nodes.push(a);\n    const div=Math.max(1,Math.ceil((b-a)/step));\n    for(let j=1;j<div;j++)nodes.push(a+(b-a)*j/div);\n  }\n  nodes.push(keys[keys.length-1]);\n  return{nodes:uniqueSorted(nodes),active,feLen,mainLenFe};\n}\n\nfunction gauss(A,b){\n  const n=A.length,M=A.map(r=>r.slice()),rhs=b.slice();\n  for(let c=0;c<n;c++){\n    let piv=c,mx=Math.abs(M[c][c]);\n    for(let r=c+1;r<n;r++){const v=Math.abs(M[r][c]);if(v>mx){mx=v;piv=r}}\n    if(mx<1e-12)return null;\n    if(piv!==c){[M[c],M[piv]]=[M[piv],M[c]];[rhs[c],rhs[piv]]=[rhs[piv],rhs[c]]}\n    const d=M[c][c];\n    for(let j=c;j<n;j++)M[c][j]/=d;rhs[c]/=d;\n    for(let r=0;r<n;r++){\n      if(r===c)continue;const f=M[r][c];if(Math.abs(f)<1e-14)continue;\n      for(let j=c;j<n;j++)M[r][j]-=f*M[c][j];rhs[r]-=f*rhs[c];\n    }\n  }\n  return rhs;\n}\n\nfunction solve(wn){\n  const g=geom(wn);\n  const bn=buildNodes(g);\n  const{nodes,active,feLen,mainLenFe}=bn;\n  if(active.length<1||nodes.length<2)return{ok:false,g,active};\n  const N=nodes.length, dof=N*2;\n  const K=Array.from({length:dof},()=>new Float64Array(dof));\n  const F=new Float64Array(dof);\n\n  for(let i=0;i<N-1;i++){\n    const x1=nodes[i],x2=nodes[i+1],L=x2-x1;\n    if(L<1e-8)continue;\n    const mid=(x1+x2)/2;\n    const inNose=(wn!==undefined?wn:S.withNose)&&mid>mainLenFe+1e-6;\n    const q=inNose?S.noseW:1;\n    const EI=inNose?S.noseEI:1;\n    const k0=EI/(L*L*L);\n    const ke=[[12*k0,6*L*k0,-12*k0,6*L*k0],\n              [6*L*k0,4*L*L*k0,-6*L*k0,2*L*L*k0],\n              [-12*k0,-6*L*k0,12*k0,-6*L*k0],\n              [6*L*k0,2*L*L*k0,-6*L*k0,4*L*L*k0]];\n    const fe=[-q*L/2,-q*L*L/12,-q*L/2,q*L*L/12];\n    const m=[2*i,2*i+1,2*(i+1),2*(i+1)+1];\n    for(let r=0;r<4;r++){F[m[r]]+=fe[r];for(let c=0;c<4;c++)K[m[r]][m[c]]+=ke[r][c]}\n  }\n\n  // 支座约束：仅约束竖向位移(偶数自由度)\n  // P1(feLocal=0)处额外约束转角=0（台座侧连续支撑，等效固定端）\n  const cons=new Set();\n  for(const s of active){\n    const idx=nodes.findIndex(x=>Math.abs(x-s.feLocal)<1e-6);\n    if(idx>=0)cons.add(2*idx);\n  }\n  // P1处(feLocal=0)：约束竖向位移+转角（台座满跨支撑=固定端）\n  const p1idx=nodes.findIndex(x=>Math.abs(x)<1e-6);\n  if(p1idx>=0){cons.add(2*p1idx);cons.add(2*p1idx+1);}\n\n  const free=[];\n  for(let i=0;i<dof;i++)if(!cons.has(i))free.push(i);\n  if(free.length===0)return{ok:false,g,active};\n  const Kf=free.map(r=>free.map(c=>K[r][c]));\n  const Ff=free.map(r=>F[r]);\n  const sol=gauss(Kf,Ff);\n  if(!sol)return{ok:false,g,active};\n  const d=new Float64Array(dof);\n  for(let i=0;i<free.length;i++)d[free[i]]=sol[i];\n\n  // 由 Kd-F 回算竖向支反力。正值表示支座向上托梁；负值意味着\n  // 这个理想约束正在“向下拉”梁，真实施工支承必须另行核查。\n  const reactions=active.map(s=>{\n    const idx=nodes.findIndex(x=>Math.abs(x-s.feLocal)<1e-6);\n    if(idx<0)return{...s,value:NaN};\n    const rdof=2*idx;\n    let value=-F[rdof];\n    for(let c=0;c<dof;c++)value+=K[rdof][c]*d[c];\n    return{...s,value};\n  });\n\n  // 采样弯矩——feX就是全局x坐标（因为有限元从P1=0开始）\n  const samples=[];\n  for(let i=0;i<N-1;i++){\n    const x1=nodes[i],x2=nodes[i+1],L=x2-x1;\n    if(L<1e-8)continue;\n    const mid=(x1+x2)/2;\n    const inNose=(wn!==undefined?wn:S.withNose)&&mid>mainLenFe+1e-6;\n    const EI=inNose?S.noseEI:1;\n    const steps=5;\n    for(let s=0;s<=steps;s++){\n      if(i>0&&s===0)continue;\n      const xi=s/steps, feX=x1+xi*L;\n      const cur=((-6+12*xi)/(L*L))*d[2*i]+((-4+6*xi)/L)*d[2*i+1]+\n                ((6-12*xi)/(L*L))*d[2*(i+1)]+((-2+6*xi)/L)*d[2*(i+1)+1];\n      samples.push({local:feX,global:feX,moment:EI*cur,isMain:feX<=mainLenFe+1e-6});\n    }\n  }\n  const mainS=samples.filter(s=>s.isMain);\n  return{ok:true,g,active,reactions,d,samples,mainS,mainLenFe,\n    maxP:Math.max(0,...samples.map(s=>s.moment)),\n    maxN:Math.min(0,...samples.map(s=>s.moment)),\n    mainNeg:Math.min(0,...mainS.map(s=>s.moment))};\n}\n\n/* 在采样点中插值 */\nfunction interpM(list,lx){\n  if(lx<=list[0].local)return list[0].moment;\n  if(lx>=list[list.length-1].local)return list[list.length-1].moment;\n  for(let i=0;i<list.length-1;i++){\n    const a=list[i],b=list[i+1];\n    if(lx>=a.local-EPS&&lx<=b.local+EPS){\n      const t=(b.local-a.local)<1e-8?0:(lx-a.local)/(b.local-a.local);\n      return a.moment+t*(b.moment-a.moment);\n    }\n  }\n  return 0;\n}\n\n/* ===== 截面历程计算 ===== */\nfunction computeHistory(){\n  if(S.trackLocal<0){S.trackHistory=null;return}\n  const g0=geom(false);\n  const steps=120;\n  const ts=[],ms=[],msNose=[];\n  const savedFront=S.frontX;\n  for(let i=0;i<=steps;i++){\n    const t=i/steps;\n    S.frontX=g0.minFront+t*(g0.maxFront-g0.minFront);\n    // 截面在有限元中的坐标 = frontX - trackLocal（距P1的距离）\n    const feX=S.frontX-S.trackLocal;\n    const r=solve(false);\n    const rn=solve(true);\n    ts.push(t);\n    // 只有当截面已经悬出台座(feX>=0)时才有弯矩\n    ms.push(r.ok&&feX>=-EPS?interpM(r.mainS,feX):0);\n    msNose.push(rn.ok&&feX>=-EPS?interpM(rn.mainS,feX):0);\n  }\n  S.frontX=savedFront;\n  S.trackHistory={ts,ms,msNose};\n}\n\n/* ===== 包络计算 ===== */\nfunction computeEnvelope(){\n  const g0=geom(false);\n  const nSta=160, nStep=100;\n  // 包络横轴 = 全局x坐标（从P1=0到最后一个墩）\n  const lastPier=g0.piers[g0.piers.length-1];\n  const stations=Array.from({length:nSta+1},(_,i)=>lastPier*i/nSta);\n  const envNo={pos:new Array(nSta+1).fill(-Infinity),neg:new Array(nSta+1).fill(Infinity)};\n  const envYes={pos:new Array(nSta+1).fill(-Infinity),neg:new Array(nSta+1).fill(Infinity)};\n  const savedFront=S.frontX;\n  for(let i=0;i<=nStep;i++){\n    S.frontX=g0.minFront+(g0.maxFront-g0.minFront)*i/nStep;\n    const rNo=solve(false), rYes=solve(true);\n    for(let j=0;j<=nSta;j++){\n      if(rNo.ok&&rNo.mainS.length){const m=interpM(rNo.mainS,stations[j]);if(m>envNo.pos[j])envNo.pos[j]=m;if(m<envNo.neg[j])envNo.neg[j]=m}\n      if(rYes.ok&&rYes.mainS.length){const m=interpM(rYes.mainS,stations[j]);if(m>envYes.pos[j])envYes.pos[j]=m;if(m<envYes.neg[j])envYes.neg[j]=m}\n    }\n  }\n  S.frontX=savedFront;\n  const clean=a=>a.map(v=>Number.isFinite(v)?v:0);\n  S.envelope={stations,lastPier,noNose:{pos:clean(envNo.pos),neg:clean(envNo.neg)},\n    withNose:{pos:clean(envYes.pos),neg:clean(envYes.neg)}};\n}\n\n/* ===== SVG 工具 ===== */\nconst NS=\"http://www.w3.org/2000/svg\";\nfunction mk(tag){return document.createElementNS(NS,tag)}\nfunction clr(svg){while(svg.firstChild)svg.removeChild(svg.firstChild)}\nfunction svgMeta(svg,titleText,descText){\n  const title=mk(\"title\"),desc=mk(\"desc\");\n  title.textContent=titleText;desc.textContent=descText;\n  svg.append(title,desc);\n}\nfunction wx(x,vMin,vMax,w,mx){return mx+(x-vMin)/(vMax-vMin)*(w-2*mx)}\nfunction pts2d(pts){return pts.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join(' ')}\n\n/* ===== 渲染：结构示意图 ===== */\nfunction renderStruct(res){\n  const svg=el.svgStruct; clr(svg);\n  svgMeta(svg,\"当前顶推位置\",`主梁前端位于 ${fmt(res.g.frontX,1)} 米，${res.active.length} 个支点进入模型。`);\n  const W=960,H=260,MX=40,BY=105,GY=210;\n  const g=res.g;\n\n  // 背景\n  const bg=mk(\"rect\");bg.setAttribute(\"width\",W);bg.setAttribute(\"height\",H);\n  bg.setAttribute(\"fill\",\"#fffdf9\");svg.appendChild(bg);\n  // 地面线\n  const gl=mk(\"line\");gl.setAttribute(\"x1\",0);gl.setAttribute(\"x2\",W);\n  gl.setAttribute(\"y1\",GY);gl.setAttribute(\"y2\",GY);\n  gl.setAttribute(\"stroke\",\"rgba(29,42,54,.14)\");gl.setAttribute(\"stroke-width\",2);\n  svg.appendChild(gl);\n\n  // 所有支承：台座=P1左侧满跨支撑区域，桥墩固定\n  // 画台座区域（从视图左边到P1）\n  const p1sx=wx(0,g.vMin,g.vMax,W,MX);\n  const padRect=mk(\"rect\");\n  padRect.setAttribute(\"x\",0);padRect.setAttribute(\"y\",BY+16);\n  padRect.setAttribute(\"width\",p1sx);padRect.setAttribute(\"height\",GY-BY-16);\n  padRect.setAttribute(\"fill\",\"rgba(11,143,114,.08)\");padRect.setAttribute(\"rx\",4);\n  svg.appendChild(padRect);\n  const padLabel=mk(\"text\");padLabel.setAttribute(\"x\",Math.max(20,p1sx-40));\n  padLabel.setAttribute(\"y\",GY+20);padLabel.setAttribute(\"font-size\",\"11\");\n  padLabel.setAttribute(\"fill\",\"var(--active)\");padLabel.textContent=\"制梁台座\";\n  svg.appendChild(padLabel);\n\n  // 桥墩\n  for(let i=0;i<g.piers.length;i++){\n    const px=g.piers[i];\n    const sx=wx(px,g.vMin,g.vMax,W,MX);\n    const act=res.active.some(a=>Math.abs(a.x-px)<1e-6);\n    const tri=mk(\"polygon\");\n    tri.setAttribute(\"points\",`${sx-16},${GY} ${sx+16},${GY} ${sx+7},${BY+16} ${sx-7},${BY+16}`);\n    tri.setAttribute(\"fill\",act?\"rgba(11,143,114,.22)\":\"rgba(104,112,122,.16)\");\n    tri.setAttribute(\"stroke\",act?\"var(--active)\":\"#68707a\");\n    tri.setAttribute(\"stroke-width\",1.6);svg.appendChild(tri);\n    const ci=mk(\"circle\");ci.setAttribute(\"cx\",sx);ci.setAttribute(\"cy\",BY+7);\n    ci.setAttribute(\"r\",act?6:4.5);ci.setAttribute(\"fill\",act?\"var(--active)\":\"#68707a\");\n    svg.appendChild(ci);\n    const tx=mk(\"text\");tx.setAttribute(\"x\",sx);tx.setAttribute(\"y\",GY+20);\n    tx.setAttribute(\"text-anchor\",\"middle\");tx.setAttribute(\"font-size\",\"12\");\n    tx.setAttribute(\"fill\",\"#546471\");tx.textContent=\"P\"+(i+1);svg.appendChild(tx);\n  }\n\n  // 主梁：后端=rearX，前端=frontX\n  const bL=wx(g.rearX,g.vMin,g.vMax,W,MX);\n  const bR=wx(g.frontX,g.vMin,g.vMax,W,MX);\n  const br=mk(\"rect\");br.setAttribute(\"x\",bL);br.setAttribute(\"y\",BY-12);\n  br.setAttribute(\"width\",Math.max(1,bR-bL));br.setAttribute(\"height\",24);\n  br.setAttribute(\"rx\",10);br.setAttribute(\"fill\",\"var(--beam)\");\n  br.setAttribute(\"stroke\",\"#1a3d55\");br.setAttribute(\"stroke-width\",1.6);\n  svg.appendChild(br);\n\n  // 导梁\n  if(S.withNose&&g.nLen>0){\n    const nR=wx(g.tipX,g.vMin,g.vMax,W,MX);\n    const nr=mk(\"rect\");nr.setAttribute(\"x\",bR-1);nr.setAttribute(\"y\",BY-7);\n    nr.setAttribute(\"width\",Math.max(1,nR-bR+1));nr.setAttribute(\"height\",14);\n    nr.setAttribute(\"rx\",7);nr.setAttribute(\"fill\",\"var(--nose)\");\n    nr.setAttribute(\"stroke\",\"#8a4e10\");nr.setAttribute(\"stroke-width\",1.2);\n    svg.appendChild(nr);\n  }\n\n  // 追踪截面标记（trackLocal=距主梁前端的距离，全局坐标=frontX-trackLocal）\n  if(S.trackLocal>=0&&S.trackLocal<=g.bLen){\n    const gx=g.frontX-S.trackLocal;\n    const tx=wx(gx,g.vMin,g.vMax,W,MX);\n    const tl=mk(\"line\");tl.setAttribute(\"x1\",tx);tl.setAttribute(\"x2\",tx);\n    tl.setAttribute(\"y1\",BY-22);tl.setAttribute(\"y2\",BY+22);\n    tl.setAttribute(\"stroke\",\"var(--compare)\");tl.setAttribute(\"stroke-width\",2.5);\n    tl.setAttribute(\"stroke-dasharray\",\"4 3\");svg.appendChild(tl);\n    const tt=mk(\"text\");tt.setAttribute(\"x\",tx);tt.setAttribute(\"y\",BY-28);\n    tt.setAttribute(\"text-anchor\",\"middle\");tt.setAttribute(\"font-size\",\"11\");\n    tt.setAttribute(\"fill\",\"var(--compare)\");tt.setAttribute(\"font-weight\",\"700\");\n    tt.textContent=\"追踪\";svg.appendChild(tt);\n  }\n\n  // 标题\n  const t1=mk(\"text\");t1.setAttribute(\"x\",24);t1.setAttribute(\"y\",28);\n  t1.setAttribute(\"font-size\",\"13\");t1.setAttribute(\"font-weight\",\"700\");\n  t1.setAttribute(\"fill\",\"#243544\");\n  t1.textContent=`主梁前端 ${fmt(g.frontX,1)} m`;svg.appendChild(t1);\n  const t2=mk(\"text\");t2.setAttribute(\"x\",24);t2.setAttribute(\"y\",46);\n  t2.setAttribute(\"font-size\",\"11\");t2.setAttribute(\"fill\",\"#617381\");\n  t2.textContent=S.withNose?`导梁前端 ${fmt(g.tipX,1)} m`:\"未设置导梁\";\n  svg.appendChild(t2);\n\n  // 拖动+点击热区\n  const hit=mk(\"rect\");hit.setAttribute(\"x\",bL);hit.setAttribute(\"y\",BY-24);\n  const tipSx=wx(S.withNose?g.tipX:g.frontX,g.vMin,g.vMax,W,MX);\n  hit.setAttribute(\"width\",Math.max(12,tipSx-bL));\n  hit.setAttribute(\"height\",48);hit.setAttribute(\"fill\",\"rgba(0,0,0,0)\");\n  hit.setAttribute(\"cursor\",\"grab\");svg.appendChild(hit);\n  attachDrag(hit,g);\n  attachClick(hit,g,W,MX);\n}\n\n/* ===== 渲染：当前弯矩图 ===== */\n// 全局固定纵轴范围，避免拖动时上下跳动\nlet momentScaleFixed=0;\n\nfunction renderMoment(res){\n  const svg=el.svgMoment; clr(svg);\n  svgMeta(svg,\"当前施工阶段弯矩图\",\"蓝色在零线下表示正弯矩，红色在零线上表示负弯矩；数值以 qL² 归一化。 \");\n  const W=960,H=280,MX=40,AY=140;\n  const g=res.g;\n  if(!res.ok){\n    const t=mk(\"text\");t.setAttribute(\"x\",W/2);t.setAttribute(\"y\",H/2);\n    t.setAttribute(\"text-anchor\",\"middle\");t.setAttribute(\"font-size\",\"15\");\n    t.setAttribute(\"fill\",\"#7b8792\");t.textContent=\"支承不足\";svg.appendChild(t);return;\n  }\n  const bg=mk(\"rect\");bg.setAttribute(\"width\",W);bg.setAttribute(\"height\",H);\n  bg.setAttribute(\"fill\",\"#fffdfa\");svg.appendChild(bg);\n\n  const vL=g.vMin, vR=g.vMax;\n  // P1位置 = piers[0] = 0\n  const p1x=g.piers[0];\n  // 只取global >= P1的采样点\n  const filtered=res.samples.filter(s=>s.global>=p1x-EPS);\n\n  const ax=mk(\"line\");ax.setAttribute(\"x1\",0);ax.setAttribute(\"x2\",W);\n  ax.setAttribute(\"y1\",AY);ax.setAttribute(\"y2\",AY);\n  ax.setAttribute(\"stroke\",\"rgba(29,42,54,.2)\");ax.setAttribute(\"stroke-width\",1.5);\n  svg.appendChild(ax);\n  const lp=mk(\"text\");lp.setAttribute(\"x\",14);lp.setAttribute(\"y\",AY+60);\n  lp.setAttribute(\"font-size\",\"11\");lp.setAttribute(\"fill\",\"var(--pos)\");\n  lp.textContent=\"正弯矩 ↓\";svg.appendChild(lp);\n  const ln=mk(\"text\");ln.setAttribute(\"x\",14);ln.setAttribute(\"y\",AY-48);\n  ln.setAttribute(\"font-size\",\"11\");ln.setAttribute(\"fill\",\"var(--neg)\");\n  ln.textContent=\"负弯矩 ↑\";svg.appendChild(ln);\n\n  // 纵轴范围：手动 > 0 时用手动值，否则自动（只增不减）\n  const curMax=Math.max(0.1,...filtered.map(s=>Math.abs(s.moment)));\n  if(S.mScaleManual>0){\n    momentScaleFixed=S.mScaleManual;\n  }else{\n    if(curMax>momentScaleFixed)momentScaleFixed=curMax;\n  }\n  const scY=90/momentScaleFixed;\n\n  const pts=filtered.map(s=>[wx(s.global,vL,vR,W,MX),AY+s.moment*scY]);\n  if(pts.length<2){el.tagMoment.textContent=\"P1右侧无数据\";return;}\n\n  // 填色\n  const aP=[[pts[0][0],AY]];const aN=[[pts[0][0],AY]];\n  for(let i=0;i<pts.length;i++){\n    aP.push([pts[i][0],Math.max(AY,pts[i][1])]);\n    aN.push([pts[i][0],Math.min(AY,pts[i][1])]);\n  }\n  aP.push([pts[pts.length-1][0],AY]);aN.push([pts[pts.length-1][0],AY]);\n  const fp=mk(\"path\");fp.setAttribute(\"d\",pts2d(aP)+\" Z\");\n  fp.setAttribute(\"fill\",\"rgba(47,126,216,.16)\");svg.appendChild(fp);\n  const fn=mk(\"path\");fn.setAttribute(\"d\",pts2d(aN)+\" Z\");\n  fn.setAttribute(\"fill\",\"rgba(209,73,91,.16)\");svg.appendChild(fn);\n  const cv=mk(\"path\");cv.setAttribute(\"d\",pts2d(pts));\n  cv.setAttribute(\"fill\",\"none\");cv.setAttribute(\"stroke\",\"#1a3d55\");\n  cv.setAttribute(\"stroke-width\",2.5);cv.setAttribute(\"stroke-linejoin\",\"round\");\n  svg.appendChild(cv);\n\n  // 支点虚线（只画P1及右侧的）\n  for(const s of res.active){\n    if(s.x<p1x-EPS)continue;\n    const sx=wx(s.x,vL,vR,W,MX);\n    const dl=mk(\"line\");dl.setAttribute(\"x1\",sx);dl.setAttribute(\"x2\",sx);\n    dl.setAttribute(\"y1\",20);dl.setAttribute(\"y2\",H-20);\n    dl.setAttribute(\"stroke\",s.kind===\"pad\"?\"rgba(104,112,122,.22)\":\"rgba(11,143,114,.22)\");\n    dl.setAttribute(\"stroke-dasharray\",\"3 5\");svg.appendChild(dl);\n  }\n\n  // 追踪截面标记（trackLocal=距主梁前端距离，有限元坐标=frontX-trackLocal）\n  if(S.trackLocal>=0&&S.trackLocal<=g.bLen){\n    const feX=g.frontX-S.trackLocal; // 截面在有限元中的坐标\n    const gx=feX; // 全局坐标=有限元坐标（有限元从P1=0开始）\n    if(gx>=p1x-EPS&&feX>=-EPS){\n      const sx=wx(gx,vL,vR,W,MX);\n      const m=(res.mainS&&res.mainS.length)?interpM(res.mainS,feX):0;\n      const sy=clamp(AY+m*scY,20,H-20);\n      const tl=mk(\"line\");tl.setAttribute(\"x1\",sx);tl.setAttribute(\"x2\",sx);\n      tl.setAttribute(\"y1\",20);tl.setAttribute(\"y2\",H-20);\n      tl.setAttribute(\"stroke\",\"var(--compare)\");tl.setAttribute(\"stroke-width\",1.8);\n      tl.setAttribute(\"stroke-dasharray\",\"4 3\");svg.appendChild(tl);\n      const ci=mk(\"circle\");ci.setAttribute(\"cx\",sx);ci.setAttribute(\"cy\",sy);\n      ci.setAttribute(\"r\",5);ci.setAttribute(\"fill\",\"var(--compare)\");svg.appendChild(ci);\n      const vt=mk(\"text\");vt.setAttribute(\"x\",sx+8);vt.setAttribute(\"y\",sy-8);\n      vt.setAttribute(\"font-size\",\"11\");vt.setAttribute(\"fill\",\"var(--compare)\");\n      vt.setAttribute(\"font-weight\",\"700\");vt.textContent=`M* ${fmt(normM(m),3)}`;svg.appendChild(vt);\n    }\n  }\n  el.tagMoment.textContent=`当前弯矩 M*=M/(qL²) | 峰值 ${fmt(normM(curMax),3)}`;\n}\n\n/* ===== 渲染：截面弯矩历程 ===== */\nfunction renderHistory(){\n  const svg=el.svgHistory; clr(svg);\n  svgMeta(svg,\"所选截面的全过程弯矩历程\",\"比较无导梁实线与有导梁虚线，观察曲线是否穿越零线。 \");\n  const W=960,H=280,MX=50,MY=32,AY=H/2;\n  const bg=mk(\"rect\");bg.setAttribute(\"width\",W);bg.setAttribute(\"height\",H);\n  bg.setAttribute(\"fill\",\"#fffdfa\");svg.appendChild(bg);\n\n  if(!S.trackHistory||S.trackLocal<0){\n    const t=mk(\"text\");t.setAttribute(\"x\",W/2);t.setAttribute(\"y\",H/2);\n    t.setAttribute(\"text-anchor\",\"middle\");t.setAttribute(\"font-size\",\"14\");\n    t.setAttribute(\"fill\",\"#7b8792\");t.textContent=\"点击结构图中的梁体，选定一个追踪截面\";\n    svg.appendChild(t);el.tagHistory.textContent=\"点击梁体选定截面\";return;\n  }\n  const{ts,ms,msNose}=S.trackHistory;\n  const allV=[...ms,...msNose];\n  const maxAbs=Math.max(0.1,...allV.map(v=>Math.abs(v)));\n  const scY=(H/2-MY)/maxAbs;\n  const mapX=t=>MX+t*(W-2*MX);\n  const mapY=m=>AY+m*scY;\n\n  // 零线\n  const ax=mk(\"line\");ax.setAttribute(\"x1\",MX);ax.setAttribute(\"x2\",W-MX);\n  ax.setAttribute(\"y1\",AY);ax.setAttribute(\"y2\",AY);\n  ax.setAttribute(\"stroke\",\"rgba(29,42,54,.2)\");ax.setAttribute(\"stroke-width\",1.5);\n  svg.appendChild(ax);\n\n  // 正负填色（无导梁）\n  const pNo=ts.map((t,i)=>[mapX(t),mapY(ms[i])]);\n  const aP2=[[pNo[0][0],AY],...pNo.map(p=>[p[0],Math.max(AY,p[1])]),[pNo[pNo.length-1][0],AY]];\n  const aN2=[[pNo[0][0],AY],...pNo.map(p=>[p[0],Math.min(AY,p[1])]),[pNo[pNo.length-1][0],AY]];\n  const fP2=mk(\"path\");fP2.setAttribute(\"d\",pts2d(aP2)+\" Z\");\n  fP2.setAttribute(\"fill\",\"rgba(47,126,216,.1)\");svg.appendChild(fP2);\n  const fN2=mk(\"path\");fN2.setAttribute(\"d\",pts2d(aN2)+\" Z\");\n  fN2.setAttribute(\"fill\",\"rgba(209,73,91,.1)\");svg.appendChild(fN2);\n\n  // 无导梁曲线\n  const cNo=mk(\"path\");cNo.setAttribute(\"d\",pts2d(pNo));\n  cNo.setAttribute(\"fill\",\"none\");cNo.setAttribute(\"stroke\",\"#1a3d55\");\n  cNo.setAttribute(\"stroke-width\",2.2);svg.appendChild(cNo);\n  // 有导梁曲线\n  const pYes=ts.map((t,i)=>[mapX(t),mapY(msNose[i])]);\n  const cYes=mk(\"path\");cYes.setAttribute(\"d\",pts2d(pYes));\n  cYes.setAttribute(\"fill\",\"none\");cYes.setAttribute(\"stroke\",\"var(--active)\");\n  cYes.setAttribute(\"stroke-width\",2);cYes.setAttribute(\"stroke-dasharray\",\"6 4\");\n  svg.appendChild(cYes);\n\n  // 当前位置竖线\n  const cx=mapX(S.posT);\n  const cl=mk(\"line\");cl.setAttribute(\"x1\",cx);cl.setAttribute(\"x2\",cx);\n  cl.setAttribute(\"y1\",MY);cl.setAttribute(\"y2\",H-MY);\n  cl.setAttribute(\"stroke\",\"rgba(106,76,255,.35)\");cl.setAttribute(\"stroke-width\",1.5);\n  svg.appendChild(cl);\n\n  // 标注\n  const lb1=mk(\"text\");lb1.setAttribute(\"x\",MX);lb1.setAttribute(\"y\",20);\n  lb1.setAttribute(\"font-size\",\"12\");lb1.setAttribute(\"font-weight\",\"700\");\n  lb1.setAttribute(\"fill\",\"#243544\");\n  lb1.textContent=`距前端 ${fmt(S.trackLocal,1)}m 处截面弯矩历程`;svg.appendChild(lb1);\n  const lb2=mk(\"text\");lb2.setAttribute(\"x\",W-MX);lb2.setAttribute(\"y\",20);\n  lb2.setAttribute(\"text-anchor\",\"end\");lb2.setAttribute(\"font-size\",\"11\");\n  lb2.setAttribute(\"fill\",\"#617381\");\n  lb2.textContent=\"实线=无导梁  虚线=有导梁\";svg.appendChild(lb2);\n  const xa=mk(\"text\");xa.setAttribute(\"x\",W/2);xa.setAttribute(\"y\",H-6);\n  xa.setAttribute(\"text-anchor\",\"middle\");xa.setAttribute(\"font-size\",\"11\");\n  xa.setAttribute(\"fill\",\"#617381\");xa.textContent=\"顶推进度 →\";svg.appendChild(xa);\n\n  el.tagHistory.textContent=`距前端 ${fmt(S.trackLocal,1)}m | 最大正 ${fmt(Math.max(0,...ms))} 最大负 ${fmt(Math.min(0,...ms))}`;\n}\n\n/* ===== 渲染：全过程包络 ===== */\nfunction renderEnvelope(){\n  const svg=el.svgEnvelope; clr(svg);\n  svgMeta(svg,\"全过程弯矩包络\",\"比较主梁各位置在全部施工阶段出现过的最大正弯矩和最小负弯矩。 \");\n  const W=960,H=280,MX=50,MY=32,AY=H/2;\n  const bg=mk(\"rect\");bg.setAttribute(\"width\",W);bg.setAttribute(\"height\",H);\n  bg.setAttribute(\"fill\",\"#fffdfa\");svg.appendChild(bg);\n  const g0=geom(false);\n\n  // 墩位虚线\n  for(let i=0;i<S.nPier;i++){\n    const x=MX+(g0.piers[g0.piers.length-1]===0?0:(i*S.span/g0.piers[g0.piers.length-1])*(W-2*MX));\n    const dl=mk(\"line\");dl.setAttribute(\"x1\",x);dl.setAttribute(\"x2\",x);\n    dl.setAttribute(\"y1\",MY);dl.setAttribute(\"y2\",H-MY);\n    dl.setAttribute(\"stroke\",\"rgba(29,42,54,.07)\");dl.setAttribute(\"stroke-dasharray\",\"3 6\");\n    svg.appendChild(dl);\n    const tx=mk(\"text\");tx.setAttribute(\"x\",x);tx.setAttribute(\"y\",H-6);\n    tx.setAttribute(\"text-anchor\",\"middle\");tx.setAttribute(\"font-size\",\"10\");\n    tx.setAttribute(\"fill\",\"#617381\");tx.textContent=i===0?\"起点\":\"P\"+(i+1);\n    svg.appendChild(tx);\n  }\n\n  // 零线\n  const ax=mk(\"line\");ax.setAttribute(\"x1\",MX);ax.setAttribute(\"x2\",W-MX);\n  ax.setAttribute(\"y1\",AY);ax.setAttribute(\"y2\",AY);\n  ax.setAttribute(\"stroke\",\"rgba(29,42,54,.2)\");ax.setAttribute(\"stroke-width\",1.5);\n  svg.appendChild(ax);\n\n  if(!S.envelope){\n    const t=mk(\"text\");t.setAttribute(\"x\",W/2);t.setAttribute(\"y\",H/2-10);\n    t.setAttribute(\"text-anchor\",\"middle\");t.setAttribute(\"font-size\",\"14\");\n    t.setAttribute(\"fill\",\"#7b8792\");t.textContent=\"点击「计算包络」后显示\";\n    svg.appendChild(t);el.tagEnvelope.textContent=\"尚未计算\";return;\n  }\n\n  const env=S.envelope;\n  const allV=[...env.noNose.pos,...env.noNose.neg,...env.withNose.pos,...env.withNose.neg];\n  const maxAbs=Math.max(0.15,...allV.map(v=>Math.abs(v)));\n  const scY=(H/2-MY)/maxAbs;\n  const mapX=local=>MX+(env.lastPier<1e-6?0:local/env.lastPier*(W-2*MX));\n  const mapY=m=>AY+m*scY;\n\n  function drawSet(key,posFill,negFill,posStroke,negStroke,w,dash){\n    const set=env[key];\n    const pP=env.stations.map((x,i)=>[mapX(x),mapY(set.pos[i])]);\n    const pN=env.stations.map((x,i)=>[mapX(x),mapY(set.neg[i])]);\n    // 填色\n    const aP=[[pP[0][0],AY],...pP,[pP[pP.length-1][0],AY]];\n    const aN=[[pN[0][0],AY],...pN,[pN[pN.length-1][0],AY]];\n    const fP=mk(\"path\");fP.setAttribute(\"d\",pts2d(aP)+\" Z\");fP.setAttribute(\"fill\",posFill);svg.appendChild(fP);\n    const fN=mk(\"path\");fN.setAttribute(\"d\",pts2d(aN)+\" Z\");fN.setAttribute(\"fill\",negFill);svg.appendChild(fN);\n    // 曲线\n    const cP=mk(\"path\");cP.setAttribute(\"d\",pts2d(pP));cP.setAttribute(\"fill\",\"none\");\n    cP.setAttribute(\"stroke\",posStroke);cP.setAttribute(\"stroke-width\",w);\n    if(dash)cP.setAttribute(\"stroke-dasharray\",dash);svg.appendChild(cP);\n    const cN=mk(\"path\");cN.setAttribute(\"d\",pts2d(pN));cN.setAttribute(\"fill\",\"none\");\n    cN.setAttribute(\"stroke\",negStroke);cN.setAttribute(\"stroke-width\",w);\n    if(dash)cN.setAttribute(\"stroke-dasharray\",dash);svg.appendChild(cN);\n  }\n\n  drawSet(\"noNose\",\"rgba(47,126,216,.08)\",\"rgba(209,73,91,.08)\",\n    \"rgba(47,126,216,.5)\",\"rgba(209,73,91,.5)\",2,\"7 5\");\n  drawSet(\"withNose\",\"rgba(11,143,114,.08)\",\"rgba(197,107,31,.08)\",\n    \"#0b8f72\",\"#c56b1f\",2.5,null);\n\n  // 图例\n  const legs=[{x:MX,c:\"rgba(47,126,216,.5)\",t:\"无导梁\",d:\"7 5\"},\n    {x:MX+130,c:\"#0b8f72\",t:\"有导梁\",d:null}];\n  for(const l of legs){\n    const ll=mk(\"line\");ll.setAttribute(\"x1\",l.x);ll.setAttribute(\"x2\",l.x+36);\n    ll.setAttribute(\"y1\",18);ll.setAttribute(\"y2\",18);ll.setAttribute(\"stroke\",l.c);\n    ll.setAttribute(\"stroke-width\",2.5);if(l.d)ll.setAttribute(\"stroke-dasharray\",l.d);\n    svg.appendChild(ll);\n    const lt=mk(\"text\");lt.setAttribute(\"x\",l.x+44);lt.setAttribute(\"y\",22);\n    lt.setAttribute(\"font-size\",\"11\");lt.setAttribute(\"fill\",\"#617381\");\n    lt.textContent=l.t;svg.appendChild(lt);\n  }\n\n  // 统计\n  const noNeg=Math.min(...env.noNose.neg);\n  const wiNeg=Math.min(...env.withNose.neg);\n  const red=Math.abs(noNeg)>1e-8?((Math.abs(noNeg)-Math.abs(wiNeg))/Math.abs(noNeg)*100):0;\n  el.tagEnvelope.textContent=`包络已计算 | 负弯矩峰值降低 ${fmt(red,1)}%`;\n  el.envSummary.textContent=\n    `全过程扫描（M*=M/(qL²)）：无导梁最不利负弯矩 ${fmt(normM(noNeg),3)}，有导梁 ${fmt(normM(wiNeg),3)}，降低 ${fmt(red,1)}%。`+\n    `正弯矩峰值：无导梁 ${fmt(normM(Math.max(...env.noNose.pos)),3)}，有导梁 ${fmt(normM(Math.max(...env.withNose.pos)),3)}。`;\n}\n\n/* ===== 拖动梁体 ===== */\nfunction attachDrag(hit,g){\n  hit.onpointerdown=e=>{dragging=true;hit.setPointerCapture(e.pointerId);hit.style.cursor=\"grabbing\"};\n  hit.onpointermove=e=>{\n    if(!dragging)return;\n    const rect=el.svgStruct.getBoundingClientRect();\n    const px=clamp(e.clientX-rect.left,0,rect.width);\n    const ratio=px/rect.width;\n    const modelX=g.vMin+ratio*(g.vMax-g.vMin);\n    const gf=geom(false);\n    // modelX近似为梁前端位置\n    S.frontX=clamp(modelX,gf.minFront,gf.maxFront);\n    syncToT(); render();\n  };\n  const up=e=>{dragging=false;hit.releasePointerCapture(e.pointerId);hit.style.cursor=\"grab\"};\n  hit.onpointerup=up; hit.onpointercancel=up;\n}\n\n/* ===== 点击选截面 ===== */\nfunction attachClick(hit,g,W,MX){\n  hit.addEventListener(\"click\",e=>{\n    if(dragging)return;\n    const rect=el.svgStruct.getBoundingClientRect();\n    const px=e.clientX-rect.left;\n    const ratio=px/rect.width;\n    const modelX=g.vMin+ratio*(g.vMax-g.vMin);\n    // trackLocal = 距主梁前端的距离（固定在梁上，随梁移动）\n    // 点击位置的全局坐标 modelX，主梁前端 = frontX，后端 = rearX\n    const distFromFront=g.frontX-modelX;\n    if(distFromFront>=0&&distFromFront<=g.bLen){\n      S.trackLocal=distFromFront;\n      el.rTrack.value=String(Math.round(clamp(distFromFront/g.bLen,0.05,.9)*1000));\n      computeHistory();\n      render();\n    }\n  });\n}\n\n/* ===== 阶段判断 ===== */\nfunction getStage(res){\n  if(!res.ok)return{t:\"支承不足\",n:\"请继续推进梁体\"};\n  const g=res.g;\n  const pierSup=res.active.filter(s=>s.kind===\"pier\");\n  const tipX=g.frontX+(S.withNose?g.nLen:0);\n  const lead=Math.max(...res.active.map(s=>s.x));\n  const overhang=tipX-lead;\n  if(pierSup.length===0)return{t:\"起步阶段\",n:\"主梁尚未到达第一个桥墩\"};\n  if(overhang>0.35*S.span)return{t:\"最大悬臂\",n:`前端悬臂 ${fmt(overhang,1)}m，负弯矩最敏感！`};\n  if(pierSup.length===1)return{t:\"首跨进入\",n:\"主梁正在从台座过渡到桥墩体系\"};\n  if(pierSup.length===2)return{t:\"两跨连续\",n:\"内力在两个桥跨间重新分配\"};\n  if(g.frontX>=g.piers[g.piers.length-1]-EPS)return{t:\"接近贯通\",n:\"主梁即将全部就位\"};\n  return{t:\"多跨连续\",n:`${pierSup.length}个桥墩参与受力，连续效应显著`};\n}\n\n/* ===== 更新状态卡片和教学文字 ===== */\nfunction updateStats(res){\n  const stage=getStage(res);\n  el.sStage.textContent=stage.t;\n  el.sStageN.textContent=stage.n;\n  el.sSupN.textContent=res.ok?String(res.active.length):\"0\";\n  el.sSupD.textContent=res.ok?`桥墩${res.active.filter(s=>s.kind===\"pier\").length}个`:\"\";\n  el.sMpos.textContent=res.ok?fmt(normM(res.maxP),3):\"--\";\n  el.sMneg.textContent=res.ok?fmt(normM(res.maxN),3):\"--\";\n\n  if(res.ok&&res.reactions&&res.reactions.length){\n    const minReaction=Math.min(...res.reactions.map(r=>r.value));\n    const minSupport=res.reactions.find(r=>r.value===minReaction);\n    const normalized=minReaction/S.span;\n    const needsTie=normalized<-1e-5;\n    el.sReaction.textContent=needsTie?\"需要核查\":\"都在托梁\";\n    el.sReaction.style.color=needsTie?\"var(--neg)\":\"var(--active)\";\n    el.sReactionN.textContent=`${minSupport?minSupport.label:\"支点\"} 最小 R/(qL)=${fmt(normalized,3)}`;\n  }else{\n    el.sReaction.textContent=\"--\";\n    el.sReactionN.textContent=\"检查负反力\";\n  }\n\n  // 导梁改善\n  if(res.ok){\n    const rNo=solve(false), rYes=solve(true);\n    if(rNo.ok&&rYes.ok){\n      const base=Math.abs(rNo.mainNeg), imp=Math.abs(rYes.mainNeg);\n      const red=base>1e-8?(base-imp)/base*100:0;\n      el.sImpr.textContent=`${fmt(red,1)}%`;\n      el.sImprN.textContent=`M*: ${fmt(normM(rNo.mainNeg),3)} → ${fmt(normM(rYes.mainNeg),3)}`;\n    }else{el.sImpr.textContent=\"--\";el.sImprN.textContent=\"\";}\n  }else{el.sImpr.textContent=\"--\";}\n\n  // 教学文字\n  if(!res.ok){el.teachText.textContent=\"当前支承不足，请继续推进。\";return;}\n  let txt=`${stage.t}：${stage.n}`;\n  if(S.trackLocal>=0){\n    const feX=res.g.frontX-S.trackLocal;\n    const m=(res.ok&&res.mainS&&res.mainS.length&&feX>=-EPS)?interpM(res.mainS,feX):0;\n    txt+=` | 距前端${fmt(S.trackLocal,1)}m处 当前 M*=${fmt(normM(m),3)}`;\n    if(S.trackHistory){\n      const maxP=Math.max(0,...S.trackHistory.ms);\n      const maxN=Math.min(0,...S.trackHistory.ms);\n      txt+=`，全程 M* 从 ${fmt(normM(maxN),3)} 到 ${fmt(normM(maxP),3)}`;\n    }\n  }\n  el.teachText.textContent=txt;\n}\n\n/* ===== 更新控件标签 ===== */\nfunction updateLabels(){\n  const g0=geom(false);\n  el.vPierCount.textContent=S.nPier;\n  el.vSpan.textContent=S.span+\" m\";\n  el.vNoseLen.textContent=fmt(S.noseRatio,2)+\" 跨\";\n  el.vNoseW.textContent=fmt(S.noseW,2)+\" q\";\n  el.vNoseEI.textContent=fmt(S.noseEI,2)+\" EI\";\n  el.vPos.textContent=fmt(S.frontX,1)+\" m\";\n  el.vTrack.textContent=S.trackLocal>=0?fmt(S.trackLocal,1)+\" m\":\"尚未选择\";\n  el.rPos.value=String(Math.round(S.posT*1000));\n  el.vMScale.textContent=S.mScaleManual>0?fmt(S.mScaleManual,1):\"自动\";\n}\n\n/* ===== 主渲染 ===== */\nfunction render(){\n  syncToT(); updateLabels();\n  const res=solve();\n  renderStruct(res);\n  renderMoment(res);\n  renderHistory();\n  renderEnvelope();\n  updateStats(res);\n}\n\n/* ===== 事件绑定 ===== */\nfunction bindEvents(){\n  const updateTrackedSection=()=>{\n    const g=geom(false);\n    S.trackLocal=(+el.rTrack.value/1000)*g.bLen;\n    computeHistory();\n  };\n  el.rPierCount.oninput=e=>{S.nPier=+e.target.value;syncFromT();S.envelope=null;if(S.trackLocal>=0)updateTrackedSection();momentScaleFixed=0;render()};\n  el.rSpan.oninput=e=>{S.span=+e.target.value;syncFromT();S.envelope=null;if(S.trackLocal>=0)updateTrackedSection();momentScaleFixed=0;render()};\n  el.rNoseLen.oninput=e=>{S.noseRatio=+e.target.value;S.envelope=null;render()};\n  el.rNoseW.oninput=e=>{S.noseW=+e.target.value;S.envelope=null;if(S.trackLocal>=0)computeHistory();render()};\n  el.rNoseEI.oninput=e=>{S.noseEI=+e.target.value;S.envelope=null;if(S.trackLocal>=0)computeHistory();render()};\n  el.rTrack.oninput=()=>{updateTrackedSection();render()};\n  el.rMScale.oninput=e=>{\n    const v=parseFloat(e.target.value)||0;\n    if(v<=0){S.mScaleManual=0;momentScaleFixed=0;}\n    else{S.mScaleManual=v;momentScaleFixed=v;}\n    render();\n  };\n  el.rPos.oninput=e=>{S.posT=+e.target.value/1000;syncFromT();render()};\n  el.cbNose.onchange=e=>{S.withNose=e.target.checked;render()};\n\n  el.btnReset.onclick=()=>{S.playing=false;el.btnPlay.textContent=\"▶ 播放\";S.posT=0;momentScaleFixed=0;syncFromT();render()};\n  el.btnSweep.onclick=()=>{\n    el.tagEnvelope.textContent=\"计算中...\";\n    requestAnimationFrame(()=>{\n      const saved=S.frontX;\n      computeEnvelope();\n      S.frontX=saved;syncToT();render();\n    });\n  };\n  el.btnPlay.onclick=()=>{\n    if(matchMedia('(prefers-reduced-motion: reduce)').matches){\n      S.posT=Math.min(1,S.posT+.05);\n      syncFromT();render();\n      el.btnPlay.textContent=\"向前一步\";\n      return;\n    }\n    S.playing=!S.playing;\n    el.btnPlay.textContent=S.playing?\"⏸ 暂停\":\"▶ 播放\";\n  };\n}\n\nfunction bindPrediction(){\n  const key=\"bridge-book:launching-prediction:v1\";\n  try{el.predictionText.value=localStorage.getItem(key)||\"\"}catch(_){/* sandbox may disable storage */}\n  el.savePrediction.addEventListener(\"click\",()=>{\n    const value=el.predictionText.value.trim();\n    if(!value){el.predictionStatus.textContent=\"先留一句不完整的判断也可以。\";el.predictionText.focus();return}\n    try{localStorage.setItem(key,value)}catch(_){/* current session still keeps the text */}\n    el.predictionStatus.textContent=\"留下了。操作以后，再回来看看哪一个词需要改。\";\n  });\n}\n\nfunction bindFrameResize(){\n  if(window.parent===window)return;\n  let raf=0;\n  const report=()=>{\n    cancelAnimationFrame(raf);\n    raf=requestAnimationFrame(()=>window.parent.postMessage({\n      source:\"bridge-interaction-shell\",type:\"resize\",\n      height:Math.ceil(document.documentElement.scrollHeight),layout:\"flow\"\n    },\"*\"));\n  };\n  new ResizeObserver(report).observe(document.documentElement);\n  addEventListener(\"load\",report,{once:true});\n  report();\n}\n\n/* ===== 动画循环 ===== */\nfunction tick(){\n  if(S.playing){\n    S.posT+=0.003;\n    if(S.posT>=1){S.posT=1;S.playing=false;el.btnPlay.textContent=\"▶ 播放\";}\n    syncFromT(); render();\n  }\n  requestAnimationFrame(tick);\n}\n\n/* ===== 初始化 ===== */\nsyncFromT();bindEvents();bindPrediction();render();tick();bindFrameResize();\n</script>\n</body>\n</html>\n"}];
